import{_ as n,q as s,s as a,J as t}from"./framework-4ff91fa4.js";const p={},o=t(`<h2 id="launch-与-async" tabindex="-1"><a class="header-anchor" href="#launch-与-async" aria-hidden="true">#</a> launch 与 async</h2><p>launch 返回 Job，适合不直接返回业务结果的任务。async 返回 Deferred，调用 await 得到结果。要并发开始，先创建多个 async，再分别 await。</p><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token keyword">import</span> kotlinx<span class="token punctuation">.</span>coroutines<span class="token punctuation">.</span><span class="token operator">*</span>
<span class="token keyword">suspend</span> <span class="token keyword">fun</span> <span class="token function">loadName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> String <span class="token punctuation">{</span> <span class="token function">delay</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token string-literal singleline"><span class="token string">&quot;小林&quot;</span></span> <span class="token punctuation">}</span>
<span class="token keyword">suspend</span> <span class="token keyword">fun</span> <span class="token function">loadCount</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> Int <span class="token punctuation">{</span> <span class="token function">delay</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token number">8</span> <span class="token punctuation">}</span>
<span class="token keyword">fun</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=</span> runBlocking <span class="token punctuation">{</span>
    <span class="token keyword">val</span> name <span class="token operator">=</span> async <span class="token punctuation">{</span> <span class="token function">loadName</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
    <span class="token keyword">val</span> count <span class="token operator">=</span> async <span class="token punctuation">{</span> <span class="token function">loadCount</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
    <span class="token function">println</span><span class="token punctuation">(</span><span class="token string-literal singleline"><span class="token string">&quot;</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token expression">name<span class="token punctuation">.</span><span class="token function">await</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">：</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token expression">count<span class="token punctuation">.</span><span class="token function">await</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> 章&quot;</span></span><span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果每创建一个 async 就马上 await，后一个任务尚未创建，并发收益会消失。async 也不是“异常保险箱”，普通父子关系下的失败仍会传播。</p><h2 id="调度器的职责" tabindex="-1"><a class="header-anchor" href="#调度器的职责" aria-hidden="true">#</a> 调度器的职责</h2><p>Dispatchers.Default 用于 CPU 密集计算；JVM 上的 Dispatchers.IO 适合阻塞 I/O；Main 面向 UI，需要对应平台提供实现。withContext 切换上下文并等待结果，不会像 launch 一样在调用点直接启动独立后续流程。</p><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token keyword">import</span> kotlinx<span class="token punctuation">.</span>coroutines<span class="token punctuation">.</span><span class="token operator">*</span>
<span class="token keyword">import</span> java<span class="token punctuation">.</span>io<span class="token punctuation">.</span>File
<span class="token keyword">suspend</span> <span class="token keyword">fun</span> <span class="token function">readNotes</span><span class="token punctuation">(</span>file<span class="token operator">:</span> File<span class="token punctuation">)</span><span class="token operator">:</span> String <span class="token operator">=</span> <span class="token function">withContext</span><span class="token punctuation">(</span>Dispatchers<span class="token punctuation">.</span>IO<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    file<span class="token punctuation">.</span><span class="token function">readText</span><span class="token punctuation">(</span>Charsets<span class="token punctuation">.</span>UTF_8<span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>线程切换有成本。已经提供非阻塞挂起 API 的库，不一定需要额外包裹 IO。大量 CPU 计算仍要注意取消检查与并行度。</p><h2 id="动手练习" tabindex="-1"><a class="header-anchor" href="#动手练习" aria-hidden="true">#</a> 动手练习</h2><p>同时请求三个独立数据源，并按原顺序取结果。</p><details><summary>查看参考思路</summary><p>在 coroutineScope 中使用 sources.map { async { load(it) } }.awaitAll()；load 为自己的挂起函数。</p></details><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读" aria-hidden="true">#</a> 延伸阅读</h2><p><a href="https://kotlinlang.org/docs/composing-suspending-functions.html" target="_blank" rel="noopener noreferrer">Kotlin 官方文档：composing-suspending-functions</a>。本章为原创中文学习笔记，示例以 Kotlin/JVM 为主；使用扩展库的章节需先配置依赖。</p>`,13),e=[o];function c(i,l){return s(),a("div",null,e)}const r=n(p,[["render",c],["__file","async-dispatchers.html.vue"]]);export{r as default};
